* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #101b26;
  color: #edf4e8;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #101b26;
  background-image: linear-gradient(30deg, #172734 12%, transparent 12.5%, transparent 87%, #172734 87.5%), linear-gradient(150deg, #172734 12%, transparent 12.5%, transparent 87%, #172734 87.5%);
  background-size: 28px 48px;
}

.board {
  width: min(100%, 760px);
  padding: clamp(20px, 5vw, 38px);
  border: 4px solid #344b54;
  background: #1b2a32;
  box-shadow: 8px 8px 0 #0a1219, 0 18px 55px #0007;
}

.board-header, .board-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.eyebrow, .clock-label, .column-headings { color: #8ba39a; font-size: .8rem; font-weight: 800; letter-spacing: .14em; }
.eyebrow { margin: 0 0 6px; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 2.5rem); letter-spacing: -.04em; }
.clock-box { min-width: 126px; padding: 10px 14px; text-align: right; border: 2px solid #344b54; background: #101b26; }
.clock-label { display: block; font-size: .68rem; }
#clock { display: block; color: #f4ce63; font: 800 1.9rem/1.3 ui-monospace, "Courier New", monospace; font-variant-numeric: tabular-nums; }

.column-headings, .departure { display: grid; grid-template-columns: minmax(0, 1fr) 90px 100px; align-items: center; gap: 12px; }
.column-headings { margin-top: 32px; padding: 0 14px 10px; border-bottom: 2px solid #344b54; font-size: .72rem; }
.departures { list-style: none; margin: 0; padding: 0; }
.departure { min-height: 68px; padding: 12px 14px; border-bottom: 1px solid #344b54; color: #edf4e8; font-size: 1.05rem; }
.destination { font-weight: 750; }
.departure time, .platform { font-family: ui-monospace, "Courier New", monospace; font-weight: 700; font-variant-numeric: tabular-nums; }
.platform { color: #a9c0b4; }
.departure.next { position: relative; color: #101b26; background: #f4ce63; border-bottom-color: #d8b345; }
.departure.next::before { content: "NEXT"; position: absolute; left: -4px; top: -9px; padding: 2px 6px; color: #101b26; background: #f4ce63; font-size: .65rem; font-weight: 900; letter-spacing: .08em; }
.departure.next .platform { color: #39442e; }
.departure.departed { color: #849097; background: #18242b; }
.departure.departed .platform { color: #748187; }
.board-footer { margin-top: 22px; }
#status { margin: 0; color: #a9c0b4; font-size: .95rem; }
button { min-height: 48px; padding: 10px 16px; border: 2px solid #f4ce63; border-radius: 0; color: #101b26; background: #f4ce63; font: inherit; font-weight: 800; cursor: pointer; box-shadow: 4px 4px 0 #0a1219; }
button:hover { background: #ffe18b; }
button:focus-visible { outline: 3px solid #edf4e8; outline-offset: 4px; }
button:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 #0a1219; }
button span { font-size: 1.2em; vertical-align: -1px; }

@media (max-width: 480px) {
  body { padding: 18px 12px; }
  .board { padding: 20px 14px; }
  .column-headings, .departure { grid-template-columns: minmax(0, 1fr) 66px 82px; gap: 8px; }
  .column-headings { padding-inline: 8px; font-size: .62rem; letter-spacing: .08em; }
  .departure { padding-inline: 8px; font-size: .95rem; }
  .board-footer { align-items: stretch; flex-direction: column; }
  button { width: 100%; }
}

const trains = [
  { destination: "Northport", time: "08:10", platform: "2" },
  { destination: "Riverside", time: "08:25", platform: "4" },
  { destination: "Old Town", time: "08:40", platform: "1" },
  { destination: "Pine Ridge", time: "09:00", platform: "3" },
  { destination: "Lakeside", time: "09:20", platform: "2" },
  { destination: "Westhaven", time: "09:45", platform: "5" }
];

let now = 8 * 60;
const clock = document.querySelector("#clock");
const departures = document.querySelector("#departures");
const status = document.querySelector("#status");
const advanceButton = document.querySelector("#advance");

function minutesOf(time) {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * 60 + minutes;
}

function displayTime(minutes) {
  const wrapped = ((minutes % 1440) + 1440) % 1440;
  return `${String(Math.floor(wrapped / 60)).padStart(2, "0")}:${String(wrapped % 60).padStart(2, "0")}`;
}

function render() {
  clock.textContent = displayTime(now);
  departures.replaceChildren();
  const nextIndex = trains.findIndex(train => minutesOf(train.time) > now);

  trains.forEach((train, index) => {
    const item = document.createElement("li");
    item.className = "departure";
    if (minutesOf(train.time) <= now) item.classList.add("departed");
    if (index === nextIndex) item.classList.add("next");
    item.innerHTML = `<span class="destination"></span><time></time><span class="platform"></span>`;
    item.querySelector(".destination").textContent = train.destination;
    item.querySelector("time").textContent = train.time;
    item.querySelector(".platform").textContent = train.platform;
    departures.append(item);
  });

  status.textContent = nextIndex === -1
    ? "All trains have departed for today."
    : `Next departure: ${trains[nextIndex].destination} at ${trains[nextIndex].time}.`;
}

advanceButton.addEventListener("click", () => {
  now += 5;
  render();
});

render();
